EXPECTED = {'games/3d-battle-chess/battle.js': '6715c7f20435a85375be74a44e6c04dc8b42009f0b1ab8fb4a8bd185f322738c', 'games/3d-battle-chess/boot.js': '413dabca7618b169eac790fbdb9a596a7fe4591f7a41c672ecba27608a5b6a50', 'games/3d-battle-chess/fallback-board.js': '5835906dece04de9f592c8fdcd2427504ec4e0d114c84eecd9b0c3c08910fbd2'}

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root',type=Path,default=Path.home()/'public_html')
    args=parser.parse_args(); root=args.root.resolve()
    changes=dict(PAYLOAD)
    for name, expected in EXPECTED.items():
        path=root/name
        if not path.is_file():raise SystemExit('Missing live file: '+str(path))
        digest=hashlib.sha256(path.read_bytes()).hexdigest()
        patched=hashlib.sha256(PAYLOAD[name].encode()).hexdigest()
        if digest not in (expected,patched):
            raise SystemExit('Stopped without changes: '+name+' differs from the inspected live version.')
    chess=root/'games/3d-battle-chess/index.html'
    html=chess.read_text()
    if 'id="boardMode"' not in html:raise SystemExit('Stopped: different chess controls; no files changed.')
    html=re.sub(r'<script>\s*/\* JR-BATTLE-VIEW-TOGGLE-20260924-V2 \*/.*?</script>','',html,flags=re.S)
    html=re.sub(r'src="boot\.js(?:\?[^"<>]*)?"','src="boot.js?v=20260924-real-toggle"',html)
    changes['games/3d-battle-chess/index.html']=html
    learn=root/'learn.html'
    html=learn.read_text()
    if 'learn-brand.css?v=20260924-font' not in html:
        if '</head>' not in html:raise SystemExit('Stopped: unexpected learn.html; no files changed.')
        html=html.replace('</head>','<link rel="stylesheet" href="learn-brand.css?v=20260924-font">\n</head>')
    changes['learn.html']=html
    if not (root/'assets/fonts/dm-sans-700.ttf').is_file():
        raise SystemExit('Stopped: homepage font asset is missing; no files changed.')
    changes={n:t for n,t in changes.items() if not (root/n).exists() or (root/n).read_bytes()!=t.encode()}
    if not changes:print('Both repairs are already installed.');return
    backup=root.parent/('toggle-font-backup-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f'))
    backup.mkdir()
    existed=[];created=[]
    for name in changes:
        target=root/name
        if target.exists():
            saved=backup/name;saved.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target,saved);existed.append(name)
        else:created.append(name)
    try:
        for name,content in changes.items():
            target=root/name; temp=target.with_name(target.name+'.repair-tmp')
            temp.write_text(content);temp.chmod(0o644);temp.replace(target)
        for name,content in changes.items():
            if (root/name).read_bytes()!=content.encode():raise RuntimeError('Verification failed: '+name)
    except BaseException:
        for name in existed:shutil.copy2(backup/name,root/name)
        for name in created:(root/name).unlink(missing_ok=True)
        raise
    print('Installed and verified: bidirectional chess toggle and homepage-matched learning header font.')
    print('Backup: '+str(backup))
if __name__=='__main__':main()
